%% =====================================================================
%%  BLOOD DONOR ELIGIBILITY EXPERT SYSTEM  (Sri Lanka - NBTS criteria)
%%  Entry point.   Run:  swipl src/main.pl     then open http://localhost:8080
%%  Files: knowledge_base.pl  facts + rules (with sources)
%%         inference_engine.pl forward + backward chaining
%%         explanation.pl      reasoning / proof tree
%%         web_ui.pl           web interface (HTML generated by Prolog)
%%         ../tests/           test cases
%% =====================================================================

:- use_module(library(http/thread_httpd)).
:- use_module(library(http/http_dispatch)).
:- use_module(library(http/http_parameters)).
:- use_module(library(sgml)).
:- use_module(library(lists)).
:- use_module(library(apply)).
:- use_module(library(yall)).
:- use_module(library(www_browser)).

:- initialization(main, main).

:- include('inference_engine.pl').
:- include('knowledge_base.pl').
:- include('explanation.pl').
:- include('../tests/test_expert_system.pl').
:- include('web_ui.pl').

%% =====================================================================
%%  MAIN
%% =====================================================================
main :-
    Port = 8080,
    catch(http_server(http_dispatch, [port(Port)]), E,
          ( print_message(error, E),
            format("Could not start the server on port ~w (is it already running?)~n", [Port]),
            halt(1) )),
    format("~n=====================================================~n"),
    format("  Blood Donor Eligibility Expert System is running~n"),
    format("  Open in your browser:  http://localhost:~w~n", [Port]),
    format("  Press Ctrl+C twice to stop.~n"),
    format("=====================================================~n"),
    format(atom(URL), "http://localhost:~w", [Port]),
    catch(www_open_url(URL), _, true),
    thread_get_message(_).
